package com.essde342.triggerbot.ui.imple; import com.essde342.triggerbot.ui.ISetting; import java.util.function.Consumer; public class BooleanSetting implements ISetting{private final String name;private boolean enabled;private final Consumer<Boolean> cb;public BooleanSetting(String n,boolean v){this(n,v,null);}public BooleanSetting(String n,boolean v,Consumer<Boolean> c){name=n;enabled=v;cb=c;}public String getName(){return name;}public boolean isEnabled(){return enabled;}public void toggle(){setEnabled(!enabled);}public void setEnabled(boolean v){enabled=v;if(cb!=null)cb.accept(v);}public Object getValue(){return enabled;}public void fromString(String v){if(v!=null)setEnabled(Boolean.parseBoolean(v));}}